@validator('repo_url')
def validate_github_url(cls, v):
    url_str = str(v)
    if 'github.com' not in url_str:
        raise ValueError('Must be a GitHub repository URL')
    # Validate format
    if not re.match(r'^https://github\.com/[\w-]+/[\w.-]+/?$', url_str):
        raise ValueError('Invalid GitHub URL format')
    # Check against blocklist
    if any(blocked in url_str.lower() for blocked in BLOCKED_REPOS):
        raise ValueError('Repository is blocked')
    return v
